def boot_argv(args, directory, save=None):
    argv = ['taskset', '-c', args.cores, str(args.binary.resolve()), '--bind', '127.0.0.1',
            '--port', str(args.port), '--dir', str(directory), '--shards', '16',
            '--thread-mode', args.mode, '--net-io', args.net_io,
            '--appendonly', 'no']
    if args.mode == '2s':
        argv += ['--ratio', args.ratio]
    if save is not None:
        argv += ['--save', save]
    return argv

def args(self, mode, directory, extra, config):
    args = ['taskset', '-c', '68-79', str(self.binary)]
    if config:
        args.append(str(config))
    args += ['--bind', '127.0.0.1', '--port', str(self.port), '--shards', '16',
             '--thread-mode', mode, '--save', '', '--dir', str(directory),
             '--enable-debug-command', 'yes']
    if mode == '2s':
        args += ['--ratio', '6:2']
    return args + list(extra)
